import { useState, useEffect } from "react";
import { getAllMenus, createMenu, updateMenu, deleteMenu } from "../services/api";

function EditMenu() {
  const [menus, setMenus] = useState([]);
  const [formData, setFormData] = useState({
    day: "",
    breakfast: "",
    lunch: "",
    dinner: ""
  });
  const [editingId, setEditingId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  // Fetch all menus on component mount
  useEffect(() => {
    fetchMenus();
  }, []);

  const fetchMenus = async () => {
    try {
      const response = await getAllMenus();
      setMenus(response.data);
    } catch (error) {
      console.error("Error fetching menus:", error);
      setMessage("Failed to fetch menus");
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage("");

    if (!formData.day || !formData.breakfast || !formData.lunch || !formData.dinner) {
      setMessage("All fields are required");
      setLoading(false);
      return;
    }

    try {
      if (editingId) {
        // Update existing menu
        await updateMenu(editingId, formData);
        setMessage("Menu updated successfully");
        setEditingId(null);
      } else {
        // Create new menu
        await createMenu(formData);
        setMessage("Menu created successfully");
      }

      // Reset form
      setFormData({
        day: "",
        breakfast: "",
        lunch: "",
        dinner: ""
      });

      // Refresh menu list
      fetchMenus();
    } catch (error) {
      console.error("Error saving menu:", error);
      setMessage("Failed to save menu: " + (error.response?.data?.message || error.message));
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (menu) => {
    setFormData({
      day: menu.day,
      breakfast: menu.breakfast,
      lunch: menu.lunch,
      dinner: menu.dinner
    });
    setEditingId(menu.id);
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to delete this menu?")) {
      try {
        await deleteMenu(id);
        setMessage("Menu deleted successfully");
        fetchMenus();
      } catch (error) {
        console.error("Error deleting menu:", error);
        setMessage("Failed to delete menu");
      }
    }
  };

  const handleCancel = () => {
    setFormData({
      day: "",
      breakfast: "",
      lunch: "",
      dinner: ""
    });
    setEditingId(null);
  };

  return (
    <div className="main-content">
      <div className="container">
        <h1>Menu Management</h1>

        {message && <div className="message">{message}</div>}

        <div className="form-container">
          <h2>{editingId ? "Edit Menu" : "Add New Menu"}</h2>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Day:</label>
              <input
                type="text"
                name="day"
                value={formData.day}
                onChange={handleChange}
                placeholder="e.g., Monday"
                required
              />
            </div>

            <div className="form-group">
              <label>Breakfast:</label>
              <input
                type="text"
                name="breakfast"
                value={formData.breakfast}
                onChange={handleChange}
                placeholder="e.g., Poha & Tea"
                required
              />
            </div>

            <div className="form-group">
              <label>Lunch:</label>
              <input
                type="text"
                name="lunch"
                value={formData.lunch}
                onChange={handleChange}
                placeholder="e.g., Dal, Rice, Roti"
                required
              />
            </div>

            <div className="form-group">
              <label>Dinner:</label>
              <input
                type="text"
                name="dinner"
                value={formData.dinner}
                onChange={handleChange}
                placeholder="e.g., Paneer Sabji & Roti"
                required
              />
            </div>

            <div className="button-group">
              <button type="submit" disabled={loading}>
                {loading ? "Saving..." : editingId ? "Update Menu" : "Add Menu"}
              </button>
              {editingId && (
                <button type="button" onClick={handleCancel}>
                  Cancel
                </button>
              )}
            </div>
          </form>
        </div>

        <div className="menu-list">
          <h2>All Menus</h2>
          {menus.length === 0 ? (
            <p>No menus available</p>
          ) : (
            <table className="menu-table">
              <thead>
                <tr>
                  <th>Day</th>
                  <th>Breakfast</th>
                  <th>Lunch</th>
                  <th>Dinner</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {menus.map((menu) => (
                  <tr key={menu.id}>
                    <td>{menu.day}</td>
                    <td>{menu.breakfast}</td>
                    <td>{menu.lunch}</td>
                    <td>{menu.dinner}</td>
                    <td>
                      <button
                        className="btn-edit"
                        onClick={() => handleEdit(menu)}
                      >
                        Edit
                      </button>
                      <button
                        className="btn-delete"
                        onClick={() => handleDelete(menu.id)}
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}

export default EditMenu;
